// 切换多源知识库选项卡 (Local/Lark/NotebookLM/IMA)
function switchKbTab(tabId, btn) {
  const contents = document.querySelectorAll('.kb-tab-content');
  contents.forEach(c => c.style.display = 'none');
  const activeContent = document.getElementById(`kb-tab-${tabId}`);
  if (activeContent) activeContent.style.display = 'block';
  const buttons = document.querySelectorAll('.kb-tab-btn');
  buttons.forEach(b => {
    b.style.color = 'var(--text-muted)';
    b.classList.remove('active');
  });
  btn.style.color = 'var(--text-main)';
  btn.classList.add('active');
}

